function shellCopyFor(locale: LegacyDesktopLocaleId): Partial<DesktopCatalog> {
  return Object.fromEntries(Object.entries(shellCopyRows).map(([key, values]) => [key, values[locale]])) as Partial<DesktopCatalog>;
}

export const shellCopyTranslations: Record<LegacyDesktopLocaleId, Partial<DesktopCatalog>> = {
  en: shellCopyFor('en'),
  de: shellCopyFor('de'),
  it: shellCopyFor('it'),
  es: shellCopyFor('es'),
  fr: shellCopyFor('fr'),
  'pt-BR': shellCopyFor('pt-BR'),
  ru: shellCopyFor('ru')
};

